package org.eclipse.kura.core.token.jwt;

import static org.eclipse.kura.core.token.jwt.TestJwtServiceOCD.aConfiguration;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.kura.security.token.jwt.JwtIssueRequest;
import org.junit.Test;

public class IssuedTokenClaimsTest extends JwtServiceTestBase {

    private static final String CONFIGURED_ISSUER = "my-gateway";
    private static final String RECONFIGURED_ISSUER = "my-other-gateway";

    @Test
    public void theIssuedTokenIsAnRs256SignedJwt() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenATokenIsIssued(JwtIssueRequest.builder().build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenIsAnRs256Jwt();
        thenTheIssuedTokenHasKeyId(SIGNING_KEY_ALIAS);
    }

    @Test
    public void theIssuedTokenCarriesTheConfiguredIssuer() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenATokenIsIssued(JwtIssueRequest.builder().subject("bob").build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenHasStringClaim("iss", CONFIGURED_ISSUER);
    }

    @Test
    public void theConfiguredIssuerIsUsedAfterReconfiguration() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);
        givenConfiguration(aConfiguration().withIssuer(RECONFIGURED_ISSUER));

        whenTheServiceIsUpdated();

        thenIssuingIsPossible();
        thenTheIssuedTokenHasStringClaim("iss", RECONFIGURED_ISSUER);
    }

    @Test
    public void theIssuerClaimCannotBeOverriddenByTheRequest() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenAnIssueRequestIsBuiltWithClaim("iss", "an-impostor");

        thenAnExceptionOfTypeIsThrown(IllegalArgumentException.class);
    }

    @Test
    public void theIssuedTokenCarriesAnIssuedAtClaim() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenATokenIsIssued(JwtIssueRequest.builder().build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenWasIssuedWithinTheIssuingWindow();
    }

    @Test
    public void optionalRegisteredClaimsArePropagatedFromTheRequest() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        final Instant notBefore = Instant.now().plus(30, ChronoUnit.SECONDS).truncatedTo(ChronoUnit.SECONDS);

        whenATokenIsIssued(JwtIssueRequest.builder() //
                .subject("bob") //
                .jti("token-42") //
                .notBefore(notBefore) //
                .build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenHasStringClaim("sub", "bob");
        thenTheIssuedTokenHasStringClaim("jti", "token-42");
        thenTheIssuedTokenHasNumericClaim("nbf", notBefore.getEpochSecond());
    }

    @Test
    public void optionalRegisteredClaimsAreAbsentWhenNotRequested() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenATokenIsIssued(JwtIssueRequest.builder().build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenHasNoClaim("sub");
        thenTheIssuedTokenHasNoClaim("jti");
        thenTheIssuedTokenHasNoClaim("nbf");
        thenTheIssuedTokenHasNoClaim("aud");
    }

    @Test
    public void aSingleAudienceIsEncodedAsAJsonString() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenATokenIsIssued(JwtIssueRequest.builder().audience(Set.of("solo")).build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenHasAudienceEncodedAsAString("solo");
    }

    @Test
    public void multipleAudiencesAreEncodedAsAJsonArrayInRequestOrder() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenATokenIsIssued(JwtIssueRequest.builder().audience(orderedSet("gamma", "alpha", "beta")).build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenHasAudienceEncodedAsAnArray(List.of("gamma", "alpha", "beta"));
    }

    @Test
    public void theAudienceClaimIsOmittedWhenNoAudienceIsRequested() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        whenATokenIsIssued(JwtIssueRequest.builder().subject("bob").build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenHasNoClaim("aud");
    }

    @Test
    public void aNotBeforeAfterTheExpirationIsIssuedButNeverVerifiable() {
        givenAnActiveServiceIssuingFor(CONFIGURED_ISSUER);

        final Instant notBefore = Instant.now().plus(2, ChronoUnit.HOURS).truncatedTo(ChronoUnit.SECONDS);

        whenATokenIsIssued(JwtIssueRequest.builder().notBefore(notBefore).build());

        thenTheTokenIsIssued();
        thenTheIssuedTokenHasNumericClaim("nbf", notBefore.getEpochSecond());
        whenTheIssuedTokenIsVerified();
        thenTheFailureIsAnUnacceptableToken();
    }

    private void givenAnActiveServiceIssuingFor(final String issuer) {
        givenConfiguration(aConfiguration().withIssuer(issuer));
        givenASigningKey();
        givenABoundKeystore();
        givenAnActiveService();
    }

    private static Set<String> orderedSet(final String... values) {
        return new LinkedHashSet<>(List.of(values));
    }

}
